import type { SessionRateLimit } from 'claude-code'
import { floorOf, reserveOf, spanOf, watchedKinds } from './config.ts'
import type { Effective, Spans } from './config.ts'
import {
  CHECK_MS,
  answers,
  answersQuestion,
  coveringConsent,
  decide,
  endOf,
  endedFloor,
  extendedReal,
  floorEnded,
  heldPast,
  holdsPast,
  joinReal,
  keyStage,
  mergeStopped,
