import type { Answered, Consent, Holder, Mode, Phase, Site, StoppedRecord, Tomb, Verdict, Viewed } from './decide.ts'
import {
  FALLBACK_MS,
  KINDS,
  LIMIT_PCT,
  atLimit,
  atPoint,
  basis,
  holdEndOf,
  inResetMargin,
  inWindow,
  isTripped,
  marginOf,
  parseReset,
  pctOf,
  pointOf,
  skipStartOf,
  viewOf,
  windowMs,
} from './reading.ts'
import type { Anchored, Basis, Kind, Memory, TestSpec } from './reading.ts'
import {
  HELD_WAITS,
  atText,
  clockText,
  consentWarning,
  debugLine,
  factsOf,
  fmtPct,
  headlessText,
  leadText,
  notStarted,
  notice,
  pauseInstruction,
  pausedText,
